    customCLabel: 'custom_c (62 bits / 15.5 hex chars)',
    customCDesc: 'Occupies octet 8 bits 0–5 and octets 9–15. Application-defined for payload entropy, cryptographic nonces, or device IDs.',
    binaryLabel: '128-Bit Binary Alignment',
    errorInvalidHex: 'Invalid characters in custom input. Only hexadecimal characters [0-9, a-f, A-F] are allowed.',
    errorTooLong: 'Hexadecimal input is too long: maximum 32 hex characters (128 bits).',
